        #region Discover Stub Files
        public void InitQuery()
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.InitQuery"))
            {

                if (Site != null)
                {
                    bool isLoaded = false;
                    if (mSqlConn == null || mQueryService == null)
                    {
                        isLoaded = true;
                    }
                    else if (!mSiteId.Equals(Site.ID))
                    {
                        mSiteId = Site.ID;
                        isLoaded = true;
                    }

                    if (isLoaded)
                    {
                        mSqlConn = new AveSqlConnection(Site.ContentDatabase.DatabaseConnectionString);
                        mQueryService = AveQueryServiceProvider.Instance<IAveSOIntegrationQueryService>(Site);
                    }
                }

            }

        }

        private void InitQuery(Guid siteId, IAveSite site)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.InitQuery_1"))
            {

                if (mSiteId != siteId)
                {
                    mSiteId = siteId;
                }
                mQueryService = AveQueryServiceProvider.Instance<IAveSOIntegrationQueryService>(site);

            }

        }

        public List<IAveFile> GetItemStubAttachments(IAveListItem listItem)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetItemStubAttachments"))
            {

            if (listItem.ID <= 0)
            {
                return null;
            }
            using (IAveWeb web = listItem.Web)
            {
                using (IAveSite site = web.Site)
                {
                    List<IAveFile> files = new List<IAveFile>();
                    InitQuery(site.ID, site);
                    var urls = QueryService.GetItemStubAttachments(listItem.Web.Site.ID, listItem.Web.ID, listItem.ParentList.ID, listItem.ID);
                    urls.ForEach(url => files.Add(listItem.ParentList.ParentWeb.GetFile(url)));
                    return files;
                }
            }

            }

        }

        public List<StubDocumentInfo> GetItemStubAttachmentsByDB(IAveListItem listItem, int startNum, int endNum, ref int totalNum)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetItemStubAttachmentsByDB"))
            {

                List<StubDocumentInfo> result = new List<StubDocumentInfo>();
                if (listItem.ID <= 0)
                {
                    return result;
                }
                InitQuery(listItem.ParentList.ParentWeb.Site.ID, listItem.ParentList.ParentWeb.Site);
                return QueryService.GetItemStubAttachmentsByDB(listItem, startNum, endNum, ref totalNum);

            }

        }

