            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetItemStubAttachmentsInFolder"))
            {

            List<IAveFile> stubAttachemntList = new List<IAveFile>();
            using (IAveWeb web = folder.ParentWeb)
