                    InitQuery(site.ID, site);

                    var urls = QueryService.GetItemStubAttachmentsInFolder(folder.ParentWeb.Site.ID, folder.ParentWeb.ID, folder.ParentList.ID, folder.UniqueId);
                    List<IAveFile> files = new List<IAveFile>();
                    urls.ForEach(url => files.Add(web.GetFile(url)));
                    return files;
                }
            }

            }

        }

