        public List<IAveFile> GetStubFilesInFolder(IAveFolder folder)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetStubFilesInFolder"))
            {

                List<IAveFile> stubFileList = new List<IAveFile>();

                using (IAveWeb web = folder.ParentWeb)
                {
                    using (IAveSite site = web.Site)
                    {
                        InitQuery(site.ID, site);
                    List<IAveFile> files = new List<IAveFile>();
                    foreach (string url in QueryService.GetStubFilesUrlInFolder(site.ID, folder.UniqueId))
                    {
                        try
                        {
                            files.Add(web.GetFile(url));
                        }
                        catch (Exception ex)
                        {
                            logger.Log(AveLogLevel.WARN, "An error occurred while adding item to stub file list.Error Message: {0}", ex);
                        }
                    }
                    return files;
                }
                }

            }

        }

