        public void UpdateSOFileStream(SPFile file, Stream stream, bool CheckOutVersion = false, bool clearDocStreams = true)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.UpdateSOFileStream"))
            {

                if (StorageInfo.StorageType == AveStorageType.RBS)
                {
                    AveRBSRestore rbsRestore = new AveRBSRestore(file.Web.Site.ID, this.QueryService as IAveBackupRestoreQueryService);
                    try
                    {
                        foreach (var shredInfo in StorageInfo.ShredStubInfoList)
                        {
                            if (shredInfo.RBSInfo.RBSId != null)
                            {
                                shredInfo.RBSInfo.newRBSId = rbsRestore.RestoreRBSStub(shredInfo.RBSInfo);
                                if (shredInfo.RBSInfo.newRBSId == null)
                                {
                                    shredInfo.RBSInfo.newRBSId = shredInfo.RBSInfo.RBSId;
                                }
                            }
                        }

                        //rbsRestore.RestoreDocsToStreamsAndDocStreams(file.Web.Site.ID, file.UniqueId, StorageInfo.ShredStubInfoList[0].RBSInfo.histVersion, CheckOutVersion ? (byte)255 : StorageInfo.ShredStubInfoList[0].RBSInfo.level, StorageInfo.ShredStubInfoList, clearDocStreams);
                        rbsRestore.RestoreDocsToStreamsAndDocStreams(file.Web.Site.ID, file.UniqueId, StorageInfo.ShredStubInfoList[0].RBSInfo.histVersion, (byte)file.Level, StorageInfo.ShredStubInfoList, clearDocStreams);

                        QueryService.UpdateContentNative13(StorageInfo.ShredStubInfoList, file.Web.Site.ID, file.UniqueId, stream);
                    }
                    catch (Exception e)
                    {
                        logger.Log(AveLogLevel.DEBUG, ServerAPIResource.RestoreStorageInfoError, e.ToString());
                    }
                }


            }

        }

        #region Get Stub Label Stream
        public SpecialFileType GetSOSpecialFileType(string fileName)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetSOSpecialFileType"))
            {

                SpecialFileType soSpecialFileType = SpecialFileType.Unknown;
                string fileExtension = Path.GetExtension(fileName).ToLower(CultureInfo.InvariantCulture);
                switch (fileExtension)
                {
                    #region Deal with Web Page
                    case ".mht":
                    case ".mhtml":
                    case ".htm":
                    case ".html":
                    case ".aspx":
                        soSpecialFileType = SpecialFileType.WebPage;
                        break;
                    #endregion

                    #region Deal with Picture Files
                    case ".jpeg":
                    case ".gif":
                    case ".jpg":
                    case ".png":
                    case ".bmp":
                    case ".pic":
                    case ".tiff":
                    case ".ico":
                    case ".iff":
                    case ".lbm":
                    case ".mag":
                    case ".mac":
                    case ".mpt":
                    case ".opt":
                        soSpecialFileType = SpecialFileType.Image;
                        break;
                    #endregion

                    #region Deal with Office PPT Files
                    case ".ppt":
                    case ".pptx":
                        soSpecialFileType = SpecialFileType.PPT;
                        break;
                    #endregion
                    default:
                        soSpecialFileType = SpecialFileType.Default;
                        break;
                }
                return soSpecialFileType;

            }

        }

        [SuppressMessage("FxCopCustomRules", "C100007:SpellCheckStringValues", Justification = "Used in SharePoint web part content.")]
        public Stream GetLabelStream(string fileName)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetLabelStream"))
            {

                byte[] tempBuffer = new Guid("1c834929-4f7d-4ac5-a3a7-a13fd8578ec7").ToByteArray();
                switch (GetSOSpecialFileType(fileName))
                {
                    #region Deal with Web Page
                    case SpecialFileType.WebPage:
                        {
                            const string MHT_FILE_CONTENT = "From:\"\"\nSubject:\nDateat, 21 Nov 2009 11:31:01 +0800\nMIME-Version:1.0\nContent-Type:text/html;\nContent-Transfer-Encoding:\nContent-Location:\nX-MimeOLE:\n<HTML><HEAD></HEAD><BODY></BODY></HTML>";
                            tempBuffer = Encoding.UTF8.GetBytes(MHT_FILE_CONTENT);
                        }
                        break;
                    #endregion

                    #region Deal with Picture Files
                    case SpecialFileType.Image:
                        {
                            if (PicWidth == 0 && PicHeight == 0)
                            {
                                tempBuffer = ConvertHexStringToBytes(PICFILESTRING);
                            }
                            else
                            {
                                Bitmap fakeBit = new Bitmap(PicWidth, PicHeight);
                                MemoryStream stream = new MemoryStream();
                                fakeBit.Save(stream, ImageFormat.Jpeg);
                                stream.Seek(0L, SeekOrigin.Begin);
                                return stream;
                            }
                        }
                        break;
                    #endregion

                    #region Deal with Office PPT Files
                    case SpecialFileType.PPT:
                        if (IsSlideLibrary)//add thumbs in slide library
                        {
                            tempBuffer = ConvertHexStringToBytes(PPTFileStreamString);
                        }
                        break;
                    #endregion
                }
                return ByteArrayToStream(tempBuffer);

            }

        }

        private Stream ByteArrayToStream(byte[] bytes)
        {
            Stream stream = new MemoryStream(bytes);
            return stream;
        }

        private byte[] StreamToByteArray(Stream stream)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.StreamToByteArray"))
            {

                byte[] bytes = new byte[stream.Length];
                stream.Read(bytes, 0, bytes.Length);
                return bytes;

            }

        }

        private byte[] ConvertHexStringToBytes(string hexString)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.ConvertHexStringToBytes"))
            {

                if (hexString.StartsWith("0x", StringComparison.OrdinalIgnoreCase) && ((hexString.Length % 2) == 0))
                {
                    byte[] buffer = new byte[(hexString.Length - 2) / 2];
                    for (int i = 2; i < hexString.Length; i += 2)
                    {
                        buffer[(i / 2) - 1] = Convert.ToByte(hexString.Substring(i, 2), 0x10);
                    }
                    return buffer;
                }
                return null;

            }

        }

