        public void UpdateFileContentByNative(AveSPItemNativeInfo docInfo, Stream fs, bool useAPI = false)
        {
            UpdateStorageFileStreamByNative(docInfo, fs, useAPI);
        }

        internal void UpdateStorageFileStreamByNative(AveSPItemNativeInfo docInfo, Stream fs, bool useAPI = false)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.UpdateStorageFileStreamByNative"))
            {

            AveObjectModelFactory modelFactory = new AveServerObjectModelFactory("");
            object soIntegrationAPI = (null != modelFactory) ? modelFactory.CreateSOIntegrationAPI() : null;
            if (soIntegrationAPI == null)
            {
                if (useAPI)
                {
                    (docInfo.File as AveFile).File.SaveBinaryExtension(fs);
                }
                else
                {
                    (Site as AveSite).QueryService.UpdateFileContentByNative(docInfo, fs);
                }
                return;
            }
            string message = string.Empty;
            message = AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "InitializeForRestoreExtender",
                new Type[] { typeof(Guid), typeof(Guid), typeof(int?), typeof(int), typeof(int), typeof(AveSqlConnection) },
                new object[] { docInfo.SiteId, docInfo.ItemId, docInfo.InternalVersion, docInfo.Level, docInfo.Size, mSqlConn }) as string;
            if (!string.IsNullOrEmpty(message))
            {
                docInfo.Size = Convert.ToInt32(fs.Length);
                if (useAPI)
                {
                    (docInfo.File as AveFile).File.SaveBinaryExtension(fs);
                }
                else
                {
                    (Site as AveSite).QueryService.UpdateFileContentByNative(docInfo, fs);
                }
                return;
            }

            string tmpFile = null;
            try
            {
                using (Stream convertStream = ConvertToSeekableStream(fs, out tmpFile))
                {
                    message = AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "Restore", convertStream) as string;
                    if (!string.IsNullOrEmpty(message))
                    {
                        if (!convertStream.CanSeek)
                        {
                            throw new AveException(message);
                        }
                        convertStream.Seek(0, SeekOrigin.Begin);
                        docInfo.Size = Convert.ToInt32(convertStream.Length);
                        if (useAPI)
                        {
                            (docInfo.File as AveFile).File.SaveBinaryExtension(fs);
                        }
                        else
                        {
                            (Site as AveSite).QueryService.UpdateFileContentByNative(docInfo, fs);
                        }
                    }
                    else
                    {
                        QueryService.UpdateDocumentSize(docInfo);
                    }
                }
            }
            finally
            {
                if (!string.IsNullOrEmpty(tmpFile))
                {
                    try
                    {
                        if (File.Exists(tmpFile))
                        {
                            File.Delete(tmpFile);
                        }
                    }
                    catch (Exception ex)
                    {
                        logger.Log(AveLogLevel.DEBUG, ServerAPIResource.FileDeletedFailed, tmpFile, ex);
                    }
                }
            }

            }

        }

        public void RestoreStubDBInfo(string stubDBInfoBase64)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.RestoreStubDBInfo"))
            {

                if (StorageInfo.IsBackupLinkForArchivedData && !String.IsNullOrEmpty(stubDBInfoBase64))
                {
                    AveObjectModelFactory modelFactory = new AveServerObjectModelFactory("");
                    object soIntegrationAPI = (null != modelFactory) ? modelFactory.CreateSOIntegrationAPI() : null;
                    AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "InitializeForRestore",
                        Site.WebApplication.ID,
                        Site.WebApplication.GetResponseUri(AveUrlZone.Default).ToString(),
                        Site.ContentDatabase.DatabaseId);
                    AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "RestoreStubDBInfo", stubDBInfoBase64);
                }

            }

        }

        [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        internal static extern bool GetDiskFreeSpaceEx(string drive, out long freeBytesForUser, out long totalBytes, out long freeBytes);

        [SuppressMessage("FxCopCustomRules", "C100007:SpellCheckStringValues", Justification = "")]
        internal Stream ConvertToSeekableStream(Stream stream, out string tempFile)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.ConvertToSeekableStream"))
            {

                tempFile = null;
                if (stream.Length < MAXMEMMORYSTREAMSIZE)
                {
                    byte[] temp = new byte[stream.Length];
                    stream.Read(temp, 0, (int)stream.Length);
                    return ByteArrayToStream(temp);
                }
                else
                {
                    long freeForUser, total, free;
                    GetDiskFreeSpaceEx(AveWrapperConstants.WrapperTempFolder, out freeForUser, out total, out free);
                    if (freeForUser < stream.Length)
                    {
                        return stream;
                    }
                    tempFile = Path.Combine(AveWrapperConstants.WrapperTempFolder, Guid.NewGuid().ToString());
                    byte[] buffer = new byte[1 << 20];
                    using (FileStream fs = new FileStream(tempFile, FileMode.CreateNew))
                    {
                        int readLength = 0;
                        while ((readLength = stream.Read(buffer, 0, buffer.Length)) != 0)
                        {
                            fs.Write(buffer, 0, readLength);
                        }
                        fs.Flush();
                    }
                    return new FileStream(tempFile, FileMode.Open);
                }

            }

        }


        #region SO Integration Backup

        internal string GetStubDBInfo(IAveSite iAveSite, Guid fileUniqueID, int uiVersion, int fileLevel, byte partition, long BSN)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetStubDBInfo"))
            {


                AveObjectModelFactory modelFactory = new AveServerObjectModelFactory("");
                object soIntegrationAPI = (null != modelFactory) ? modelFactory.CreateSOIntegrationAPI() : null;
                if (null == soIntegrationAPI)
                {
                    return string.Empty;
                }
                AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "InitializeForBackup",
                    iAveSite.WebApplication.ID,
                    iAveSite.WebApplication.GetResponseUri(AveUrlZone.Default).ToString(),
                    iAveSite.ContentDatabase.DatabaseId,
                    iAveSite.ID,
                    fileUniqueID,
                    uiVersion,
                    fileLevel,
                    iAveSite.ContentDatabase.DatabaseConnectionString, partition, BSN);
                return AveAssemblyUtility.InvokeMethod(soIntegrationAPI, "BackupStubDBInfo").ToString();

            }

        }

        public AveStorageInfo BackupRBSStorageInfo(IAveSite iAveSite, Guid fileUniqueID, int uiVersion, int fileLevel, IAveBackupRestoreQueryService queryService, AveRBSStubInfo rbsInfo, byte[] RbsId)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.BackupRBSStorageInfo"))
            {

                AveStorageInfo storageInfo = new AveStorageInfo();
                storageInfo.StorageType = AveStorageType.RBS;
                storageInfo.RBSInfo = rbsInfo;
                storageInfo.RBSInfo.RBSId = RbsId;
                storageInfo.StubDataType = GetRBSDataType(storageInfo.RBSInfo.StoreBlobId);
                storageInfo.StubDBInfoBase64 = GetStubDBInfo(iAveSite, fileUniqueID, uiVersion, fileLevel, 0, 0);
                return storageInfo;

            }

        }

        public AveStorageInfo13 BackupRBSStorageInfo13(IAveSite iAveSite, Guid fileUniqueID, int uiVersion, int fileLevel, IAveBackupRestoreQueryService queryService, List<AveRBSStubInfo13> rbsInfo)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.BackupRBSStorageInfo"))
            {

                AveStorageInfo13 storageInfo = new AveStorageInfo13();
                storageInfo.StorageType = AveStorageType.RBS;

                storageInfo.ShredStubInfoList = new List<AveShredStubInfo>();

                foreach (var info in rbsInfo)
                {
                    AveShredStubInfo shredStubInfo = new AveShredStubInfo();
                    shredStubInfo.RBSInfo = info;
                    if (info.RBSId != null)
                    {
                        shredStubInfo.StubDataType = GetRBSDataType(shredStubInfo.RBSInfo.StoreBlobId);
                        shredStubInfo.StubDBInfoBase64s = GetStubDBInfo(iAveSite, fileUniqueID, uiVersion, fileLevel, info.partition, info.BSN);
                    }
                    storageInfo.ShredStubInfoList.Add(shredStubInfo);
                }

                return storageInfo;

            }

        }

        public AveStorageInfo BackupEBSStorageInfo(IAveSite iAveSite, Guid fileUniqueID, int uiVersion, int fileLevel, IAveItem item, AveBaseItemInfo baseItemInfo)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.BackupEBSStorageInfo"))
            {

                AveStorageInfo storageInfo = new AveStorageInfo();
                storageInfo.StorageType = AveStorageType.EBS;
                storageInfo.StubDataType = GetEBSDataType(item, baseItemInfo);
                storageInfo.StubDBInfoBase64 = GetStubDBInfo(iAveSite, fileUniqueID, uiVersion, fileLevel, 0, 0);
                return storageInfo;

            }

        }

        internal AveStubDataType GetEBSDataType(IAveItem item, AveBaseItemInfo baseItemInfo)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetEBSDataType"))
            {

                AveStubDataType DataType = AveStubDataType.UnKnown;
                string stubContent = item.GetStubInfoByNative(baseItemInfo);
                if (stubContent.StartsWith("AVE", StringComparison.OrdinalIgnoreCase))
                {
                    DataType = AveStubDataType.Extender;
                }
                return DataType;

            }

        }

        internal AveStubDataType GetRBSDataType(byte[] RBSBlobId)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.GetRBSDataType"))
            {

                AveStubDataType DataType = AveStubDataType.UnKnown;
                byte blobType = RBSBlobId[3];
                if ((blobType & 1) == 1)
                    DataType = AveStubDataType.Extender;
                else if ((blobType & 2) == 2)
                    DataType = AveStubDataType.Extender;
                else if ((blobType & 4) == 4)
                    DataType = AveStubDataType.Connector;
                else
                    DataType = AveStubDataType.UnKnown;
                return DataType;

            }

        }
