        #region SO Connector

        internal void RestoreConnectorItem(IAveListItem item, int uiVersion, int restoreResult, bool overwriteBlob)
        {

            using (AvePerformanceScope pc = new AvePerformanceScope("Server.AveSOIntegrationUtility.RestoreConnectorItem"))
            {

                if (mStorageInfo.IsBackupLinkForArchivedData)
                {
                    return;
                }
                if (!string.IsNullOrEmpty(errorMsg))
                {
                    throw new AveException(errorMsg);
                }
                string message = string.Empty;
                switch (restoreResult)
                {
                    case 0:
                        message = AveAssemblyUtility.InvokeMethod(ConnectorIntegrationInstance, "RestoreVersion", uiVersion, item.UniqueId, overwriteBlob) as string;
                        break;
                    case 1:
                    case 2:
                        message = AveAssemblyUtility.InvokeMethod(ConnectorIntegrationInstance, "RestoreCurrentFile", item.UniqueId, overwriteBlob) as string;
                        break;
                }

                if (!string.IsNullOrEmpty(message))
                {
                    throw new AveException(message);
                }

            }

        }

