        internal void RestoreConnectorStub(Guid uniqueId, int restoreResult, int uiVersion)
        {
            if (!string.IsNullOrEmpty(errorMsg))
            {
                throw new AveException(errorMsg);
            }
            string message = string.Empty;
            switch (restoreResult)
            {
                case 0:
                    message = AveAssemblyUtility.InvokeMethod(ConnectorIntegrationInstance, "RestoreVersionStub", uniqueId, uiVersion) as string;
                    break;
                case 1:
                case 2:
                    message = AveAssemblyUtility.InvokeMethod(ConnectorIntegrationInstance, "RestoreStub", uniqueId) as string;
                    break;
            }
            if (!string.IsNullOrEmpty(message))
            {
                throw new AveException(message);
            }
        }
